package com.bookstore.service;
import com.bookstore.entity.*; import com.bookstore.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class OrderService { private final CartRepository cart; private final OrderRepository orders; private final OrderItemRepository items; public OrderService(CartRepository c,OrderRepository o,OrderItemRepository i){cart=c;orders=o;items=i;}
 @Transactional public Order checkout(User u,String address,String payment){List<CartItem> cs=cart.findByUser(u); if(cs.isEmpty()) throw new IllegalArgumentException("Cart is empty"); double total=0; for(CartItem c:cs){if(c.getQuantity()>c.getBook().getStock())throw new IllegalArgumentException("Insufficient stock for "+c.getBook().getName()); total+=c.getQuantity()*c.getBook().getPrice();} Order o=orders.save(new Order(u,total,address,payment)); for(CartItem c:cs){Book b=c.getBook(); b.setStock(b.getStock()-c.getQuantity()); items.save(new OrderItem(o,b,c.getQuantity(),b.getPrice()));} cart.deleteByUser(u); return o; }
 public List<Order> mine(User u){return orders.findByUserOrderByCreatedAtDesc(u);} public List<Order> all(){return orders.findAll();} public Order get(Long id){return orders.findById(id).orElseThrow();} public void status(Long id,OrderStatus s){Order o=get(id);o.setStatus(s);orders.save(o);} public long count(){return orders.count();}}
